## 실제 프로젝트 예시: 전자상거래 시스템

### 1. 캡슐화 예시 - 사용자 관리
```python
class User:
    def __init__(self, email, password):
        self._email = email  # private 속성
        self.__password_hash = self._hash_password(password)
        self._login_attempts = 0

    def authenticate(self, password):
        if self._login_attempts >= 3:
            return False

        if self._verify_password(password):
            self._login_attempts = 0
            return True
        else:
            self._login_attempts += 1
            return False

    def _hash_password(self, password):  # 내부 메서드
        # 실제론 bcrypt 사용
        return hash(password)
```

### 2. 상속 예시 - 상품 관리
```python
class Product:
    def __init__(self, name, price):
        self.name = name
        self.price = price

    def calculate_total(self, quantity):
        return self.price * quantity

class DigitalProduct(Product):  # 디지털 상품
    def __init__(self, name, price, download_link):
        super().__init__(name, price)
        self.download_link = download_link

    def deliver(self):  # 디지털 상품만의 배송
        return f"다운로드 링크: {self.download_link}"

class PhysicalProduct(Product):  # 실물 상품
    def __init__(self, name, price, weight, dimensions):
        super().__init__(name, price)
        self.weight = weight
        self.dimensions = dimensions

    def calculate_shipping(self, distance):
        return self.weight * 0.1 * distance
```

### 3. 다형성 예시 - 결제 시스템
```python
class PaymentProcessor:
    def process_payment(self, amount):
        raise NotImplementedError

class CreditCardProcessor(PaymentProcessor):
    def process_payment(self, amount):
        # 신용카드 결제 로직
        return f"신용카드로 {amount}원 결제 완료"

class PayPalProcessor(PaymentProcessor):
    def process_payment(self, amount):
        # PayPal 결제 로직
        return f"PayPal로 {amount}원 결제 완료"

# 클라이언트 코드에서는 구체적인 구현을 몰라도 됨
def checkout(processor: PaymentProcessor, amount):
    return processor.process_payment(amount)  # 다형성
```

### 4. 추상화 예시 - 주문 관리
```python
from abc import ABC, abstractmethod

class OrderManager(ABC):
    @abstractmethod
    def create_order(self, items):
        pass

    @abstractmethod
    def process_order(self, order_id):
        pass

class OnlineOrderManager(OrderManager):
    def create_order(self, items):
        # 온라인 주문 생성 로직
        order = {
            'id': self._generate_id(),
            'items': items,
            'status': 'pending'
        }
        return order

    def process_order(self, order_id):
        # 복잡한 주문 처리 로직을 숨김
        self._validate_inventory()
        self._calculate_total()
        self._arrange_shipping()
        return "주문 처리 완료"
```

